//! `THIRD-PARTY-NOTICES.txt` at the repository root: the licence and notice texts of every Rust
//! crate compiled into the shipped `crossfx` binary, which the licences of those crates (MIT,
//! Apache-2.0, BSD, ISC, Zlib, Unicode and others) require to accompany a binary copy. The file
//! is generated by this test and checked by it:
//!
//! ```text
//! cargo fetch --locked
//! CROSSFX_CHECK_NOTICES=1 cargo test -p crossfx-app --test third_party_notices
//! CROSSFX_WRITE_NOTICES=1 cargo test -p crossfx-app --test third_party_notices
//! ```
//!
//! The first line puts the sources of every target's crates on disk, which both runs need: the
//! second fails when the committed file is not what `Cargo.lock` produces, and CI runs it so that
//! it fails when `Cargo.lock` changes without the file; the third rewrites the file. Neither
//! touches the network (`cargo tree` and `cargo metadata` run `--offline --locked`). Without
//! either variable the comparison is not made and the test passes with a note: a package build's
//! check, which has only its own target's crates and no network, runs the workspace's tests too.
//!
//! The crates are those `cargo tree -e normal --target <target>` lists under `crossfx-app` for
//! each build of a shipped binary ([`BUILDS`]), with the package selection that build uses; the
//! workspace's own crates are left out, and a proc-macro crate that generates part of the code is
//! kept, with what it depends on. Each crate's texts are those its sources ship in the cargo
//! registry: the files named `LICENSE*`, `COPYING*`, `NOTICE*`, `COPYRIGHT*` or `UNLICENSE*`,
//! and every file of a `LICENSES` folder, in its top folder and in the folders below, those of
//! tests, examples and benchmarks ([`NOT_COMPILED`]) and [`SKIPPED`] aside, plus [`EXTRA`]; line
//! ends normalised to LF, each text given once where several crates ship it. A crate that ships
//! none in its top folder gets the standard text of its SPDX licence with the copyright line of
//! its `authors` field, which the file says.

use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

use serde_json::Value;

/// The builds of the shipped binaries, as `(target, package selection)`, which the packaging
/// says. On Linux `cargo build --release --bin crossfx` at the workspace root (CI, which builds
/// the binary of the tarball, `.deb` and RPM; `packaging/build-tarball.sh`; `packaging/PKGBUILD`;
/// `packaging/debian/rules`, on amd64 and arm64) and Fedora's `%cargo_build` select every member
/// of the workspace; on Windows `packaging/windows/build-windows.ps1` runs
/// `cargo build --release --locked -p crossfx-app` for the setup, `.msi` and `.zip`.
const BUILDS: [(&str, &[&str]); 3] = [
    ("x86_64-unknown-linux-gnu", &["--workspace"]),
    ("aarch64-unknown-linux-gnu", &["--workspace"]),
    ("x86_64-pc-windows-msvc", &["-p", "crossfx-app"]),
];

/// The prefixes, in lower case, of the names of the files that carry a crate's licence or notice.
const PREFIXES: [&str; 6] = [
    "license",
    "licence",
    "copying",
    "notice",
    "copyright",
    "unlicense",
];

/// The folders, in lower case, that hold a crate's tests, examples or benchmarks, none of which
/// is compiled into the binary: a licence file in one covers a fixture, not the crate's code.
const NOT_COMPILED: [&str; 8] = [
    "tests",
    "test",
    "testdata",
    "fixtures",
    "examples",
    "example",
    "benches",
    "benchmarks",
];

/// Folders below a crate's top folder whose licence covers code the shipped builds do not
/// compile, as `(crate, folder in the crate)`: `tracing-core` builds `src/spin` only without its
/// `std` feature, which `tracing` turns on.
const SKIPPED: [(&str, &str); 1] = [("tracing-core", "src/spin/")];

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("the repository root exists")
}

/// One crate compiled into the binary.
struct Krate {
    name: String,
    version: String,
    licence: String,
    authors: Vec<String>,
    /// The folder of the crate's sources in the cargo registry.
    dir: PathBuf,
}

impl Krate {
    fn label(&self) -> String {
        format!("{} {}", self.name, self.version)
    }
}

/// `cargo <args>` in the repository, offline and locked, and what it printed.
fn cargo(args: &[&str]) -> Vec<u8> {
    let cargo = std::env::var_os("CARGO").unwrap_or_else(|| "cargo".into());
    let output = Command::new(cargo)
        .args(args)
        .args(["--offline", "--locked"])
        .current_dir(repo())
        .output()
        .expect("cargo runs");
    assert!(
        output.status.success(),
        "cargo {} failed (`cargo fetch --locked` puts every target's crates on disk):\n{}",
        args.join(" "),
        String::from_utf8_lossy(&output.stderr)
    );
    output.stdout
}

/// Every package of `Cargo.lock`, for every target, by `(name, version)`; those of the
/// workspace, and any other that is not from a registry, left out.
fn packages() -> HashMap<(String, String), Krate> {
    let metadata: Value = serde_json::from_slice(&cargo(&["metadata", "--format-version", "1"]))
        .expect("cargo metadata prints JSON");
    metadata["packages"]
        .as_array()
        .expect("packages")
        .iter()
        .filter(|package| !package["source"].is_null())
        .map(|package| {
            let manifest = package["manifest_path"].as_str().expect("manifest_path");
            let krate = Krate {
                name: package["name"].as_str().expect("name").to_string(),
                version: package["version"].as_str().expect("version").to_string(),
                licence: package["license"].as_str().unwrap_or("").to_string(),
                authors: package["authors"]
                    .as_array()
                    .map(|list| {
                        list.iter()
                            .filter_map(|author| author.as_str().map(str::to_string))
                            .collect()
                    })
                    .unwrap_or_default(),
                dir: Path::new(manifest)
                    .parent()
                    .expect("manifest has a folder")
                    .to_path_buf(),
            };
            ((krate.name.clone(), krate.version.clone()), krate)
        })
        .collect()
}

/// The `(name, version)` of every package `cargo tree` lists under `crossfx-app` for `target`
/// with the package `selection` of a build, through normal dependencies, the workspace's own
/// among them.
fn compiled_in(target: &str, selection: &[&str]) -> BTreeSet<(String, String)> {
    let mut args = vec!["tree"];
    args.extend_from_slice(selection);
    args.extend_from_slice(&[
        "-e",
        "normal",
        "--target",
        target,
        "--no-dedupe",
        "--prefix",
        "depth",
        "--format",
        "{p}",
    ]);
    let output = String::from_utf8(cargo(&args)).expect("cargo tree prints UTF-8");
    let mut found = BTreeSet::new();
    let mut under_app = false;
    for line in output.lines() {
        let depth_end = line
            .find(|c: char| !c.is_ascii_digit())
            .unwrap_or(line.len());
        let mut words = line[depth_end..].split_whitespace();
        let (Some(name), Some(version)) = (words.next(), words.next()) else {
            continue;
        };
        if &line[..depth_end] == "0" {
            under_app = name == "crossfx-app";
        }
        if under_app {
            let version = version
                .strip_prefix('v')
                .expect("cargo tree prints v<version>");
            found.insert((name.to_string(), version.to_string()));
        }
    }
    assert!(
        !found.is_empty(),
        "cargo tree lists nothing under crossfx-app for {target}"
    );
    found
}

/// The text of `bytes` with CRLF and lone CR line ends turned into LF and the blank space after
/// its last line dropped.
fn normalise(bytes: &[u8]) -> String {
    let text = String::from_utf8(bytes.to_vec()).expect("a licence file is UTF-8");
    let text = text.strip_prefix('\u{feff}').unwrap_or(&text);
    let text = text.replace("\r\n", "\n").replace('\r', "\n");
    text.trim_end().to_string()
}

/// Files a crate ships that carry the licence of what it bundles under a name the walk does not
/// take, as `(crate, path in the crate)`: `epaint_default_fonts` keeps the notices of its faces
/// in `fonts/`.
const EXTRA: [(&str, &str); 4] = [
    ("epaint_default_fonts", "fonts/Hack-Regular.txt"),
    ("epaint_default_fonts", "fonts/OFL.txt"),
    ("epaint_default_fonts", "fonts/UFL.txt"),
    (
        "epaint_default_fonts",
        "fonts/emoji-icon-font-mit-license.txt",
    ),
];

/// The standard text of the MIT licence, which follows the copyright line.
const MIT: &str = r#"Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction, including without limitation the rights
to use, copy, modify, merge, publish, distribute, sublicense, and/or sell
copies of the Software, and to permit persons to whom the Software is
furnished to do so, subject to the following conditions:

The above copyright notice and this permission notice shall be included in all
copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
SOFTWARE."#;

/// The standard text of the Boost Software License 1.0, which has no copyright line.
const BSL_1_0: &str = r#"Boost Software License - Version 1.0 - August 17th, 2003

Permission is hereby granted, free of charge, to any person or organization
obtaining a copy of the software and accompanying documentation covered by
this license (the "Software") to use, reproduce, display, distribute,
execute, and transmit the Software, and to prepare derivative works of the
Software, and to permit third-parties to whom the Software is furnished to
do so, all subject to the following:

The copyright notices in the Software and this entire statement, including
the above license grant, this restriction and the following disclaimer,
must be included in all copies of the Software, in whole or in part, and
all derivative works of the Software, unless such copies or derivative
works are solely in the form of machine-executable object code generated by
a source language processor.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR
IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY,
FITNESS FOR A PARTICULAR PURPOSE, TITLE AND NON-INFRINGEMENT. IN NO EVENT
SHALL THE COPYRIGHT HOLDERS OR ANYONE DISTRIBUTING THE SOFTWARE BE LIABLE
FOR ANY DAMAGES OR OTHER LIABILITY, WHETHER IN CONTRACT, TORT OR OTHERWISE,
ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER
DEALINGS IN THE SOFTWARE."#;

/// The licence and notice files of `krate` its sources ship, as `(path in the crate, text)`:
/// those in its top folder sorted by name, then those below it (see the module's header) sorted
/// by path, then the `EXTRA` ones.
fn texts_of(krate: &Krate) -> Vec<(String, String)> {
    let mut found = Vec::new();
    walk(&krate.dir, "", false, &mut found);
    found.retain(|(path, _)| {
        !SKIPPED
            .iter()
            .any(|(name, folder)| *name == krate.name && path.starts_with(folder))
    });
    found.sort_by(|a, b| (a.0.contains('/'), &a.0).cmp(&(b.0.contains('/'), &b.0)));
    for (name, path) in EXTRA {
        if name == krate.name {
            let bytes = fs::read(krate.dir.join(path)).expect("an extra notice is read");
            found.push((path.to_string(), normalise(&bytes)));
        }
    }
    found
}

/// The licence and notice files in `dir`, which is `prefix` in the crate, and in the folders
/// below it, into `found`; `in_licenses` when `dir` is a `LICENSES` folder or in one.
fn walk(dir: &Path, prefix: &str, in_licenses: bool, found: &mut Vec<(String, String)>) {
    for entry in fs::read_dir(dir).expect("a crate's folder is read") {
        let entry = entry.expect("a directory entry");
        let name = entry.file_name().to_string_lossy().to_string();
        let lower = name.to_lowercase();
        let path = format!("{prefix}{name}");
        let kind = entry.file_type().expect("file type");
        if kind.is_dir() {
            if !NOT_COMPILED.contains(&lower.as_str()) && !name.starts_with('.') {
                walk(
                    &entry.path(),
                    &format!("{path}/"),
                    in_licenses || name == "LICENSES",
                    found,
                );
            }
        } else if kind.is_file()
            && (in_licenses || PREFIXES.iter().any(|prefix| lower.starts_with(prefix)))
        {
            let text = normalise(&fs::read(entry.path()).expect("a licence file is read"));
            if !text.is_empty() {
                found.push((path, text));
            }
        }
    }
}

/// What stands in for the licence file of a crate that ships none: the standard text of each of
/// the SPDX licences of its expression that this test has the text of (of `MIT OR Apache-2.0`,
/// MIT), with the copyright line of the crate's `authors` field, and the sentence that says so.
fn standard_texts(krate: &Krate) -> Vec<(String, String)> {
    let authors: Vec<&str> = krate
        .authors
        .iter()
        .map(|author| author.split('<').next().unwrap_or(author).trim())
        .collect();
    assert!(
        !authors.is_empty(),
        "{} has neither a licence file nor authors",
        krate.label()
    );
    let line = format!("Copyright (c) {}", authors.join(", "));
    let ids: Vec<&str> = krate
        .licence
        .split(|c: char| c.is_whitespace() || c == '(' || c == ')')
        .filter(|id| !id.is_empty() && !["AND", "OR", "WITH"].contains(id))
        .collect();
    let mut texts = Vec::new();
    if ids.contains(&"MIT") {
        let note = format!(
            "No licence file ships in the sources of these crates, which are under {}. This is \
             the standard text of the MIT licence, with the copyright line of the crate's \
             authors field",
            krate.licence
        );
        texts.push((note, format!("MIT License\n\n{line}\n\n{MIT}")));
    }
    if ids.contains(&"BSL-1.0") {
        let note = format!(
            "No licence file ships in the sources of these crates, which are under {}. This is \
             the standard text of the Boost Software License 1.0, which has no copyright line \
             (the authors field of {} names {})",
            krate.licence,
            krate.label(),
            authors.join(", ")
        );
        texts.push((note, BSL_1_0.to_string()));
    }
    assert!(
        !texts.is_empty(),
        "{} ({}) ships no licence file and this test has no standard text of its licence",
        krate.label(),
        krate.licence
    );
    texts
}

/// One text of the file, with the crates that share it.
struct Group {
    /// For the texts this test supplies: the sentence that says so.
    note: Option<String>,
    text: String,
    users: Vec<String>,
}

/// The notices as the file has them.
fn generate() -> String {
    let mut known = packages();
    let mut crates: BTreeMap<(String, String), Krate> = BTreeMap::new();
    for (target, selection) in BUILDS {
        for key in compiled_in(target, selection) {
            if let Some(krate) = known.remove(&key) {
                crates.insert(key, krate);
            }
        }
    }

    // Each distinct text once, in the order of the first crate that has it, with the crates, and
    // the names of their files, that share it.
    let mut groups: Vec<Group> = Vec::new();
    let mut index: HashMap<(Option<String>, String), usize> = HashMap::new();
    for krate in crates.values() {
        let mut files: Vec<(Option<String>, String, String)> = texts_of(krate)
            .into_iter()
            .map(|(name, text)| (None, name, text))
            .collect();
        if !files.iter().any(|(_, name, _)| !name.contains('/')) {
            files.extend(
                standard_texts(krate)
                    .into_iter()
                    .map(|(note, text)| (Some(note), "standard text".to_string(), text)),
            );
        }
        for (note, name, text) in files {
            let at = *index
                .entry((note.clone(), text.clone()))
                .or_insert_with(|| {
                    groups.push(Group {
                        note,
                        text,
                        users: Vec::new(),
                    });
                    groups.len() - 1
                });
            groups[at].users.push(format!("{} ({name})", krate.label()));
        }
    }

    let rule = "=".repeat(80);
    let mut out = String::new();
    out.push_str(
        "THIRD-PARTY NOTICES\n\
         ===================\n\
         \n\
         CrossFX itself is AGPL-3.0-or-later (LICENSE). The crossfx binary is also built from the\n\
         Rust crates listed below, each under a licence of its own, which requires its text and\n\
         copyright notice to accompany copies of the binary: they follow. The notices of the\n\
         RNNoise code and of the faces compiled into the binary are shipped beside this file.\n\
         \n\
         The crates are those that cargo tree, given the target and the package selection of\n\
         each build of a shipped binary, lists under crossfx-app through normal dependencies:\n\
         \"cargo build --release --bin crossfx\", which selects every crate of the workspace, as\n\
         Fedora's %cargo_build does, for x86_64 and aarch64 Linux, and\n\
         \"cargo build --release -p crossfx-app\" for x86_64 Windows, all from Cargo.lock.\n\
         CrossFX's own crates are left out. The proc-macro crates among them generate part of\n\
         the code while it is built, and are listed with the crates they depend on.\n\
         \n\
         Each crate's licence and notice files are given: those in its top folder, and those in\n\
         the folders below it, with their path in the crate, but for the folders of tests,\n\
         examples and benchmarks and of code the builds leave out. A text that several crates\n\
         ship is given once, with the crates that ship it. Where a crate ships no licence file\n\
         in its top folder, the standard text of its licence is given with the copyright line\n\
         of the crate's authors field, and the text says so.\n\
         \n\
         This file is generated; do not edit it. With every target's crates on disk\n\
         (cargo fetch --locked), the test crates/crossfx-app/tests/third_party_notices.rs\n\
         \n\
             CROSSFX_CHECK_NOTICES=1 cargo test -p crossfx-app --test third_party_notices\n\
         \n\
         fails when the file is not what Cargo.lock produces, which CI runs, so that a change\n\
         to Cargo.lock needs a new file, and\n\
         \n\
             CROSSFX_WRITE_NOTICES=1 cargo test -p crossfx-app --test third_party_notices\n\
         \n\
         writes it.\n\
         \n",
    );
    out.push_str(&format!("Crates ({})\n-----------\n\n", crates.len()));
    for krate in crates.values() {
        out.push_str(&format!("  {}: {}\n", krate.label(), krate.licence));
    }
    for (n, group) in groups.iter().enumerate() {
        out.push_str(&format!(
            "\n\n{rule}\nText {} of {}\n{rule}\n\n",
            n + 1,
            groups.len()
        ));
        if let Some(note) = &group.note {
            out.push_str(&format!("{note}.\n\n"));
        }
        out.push_str("Crates:\n");
        for user in &group.users {
            out.push_str(&format!("  {user}\n"));
        }
        out.push_str(&format!("\n{}\n\n", "-".repeat(80)));
        out.push_str(&group.text);
        out.push('\n');
    }
    out
}

/// Whether the environment variable `name` is `1`.
fn set(name: &str) -> bool {
    std::env::var_os(name).is_some_and(|value| value == "1")
}

#[test]
fn third_party_notices_are_current() {
    let path = repo().join("THIRD-PARTY-NOTICES.txt");
    if set("CROSSFX_WRITE_NOTICES") {
        fs::write(&path, generate()).expect("THIRD-PARTY-NOTICES.txt is written");
        return;
    }
    if !set("CROSSFX_CHECK_NOTICES") {
        // Generating the file needs the crates of every target on disk, which a package build's
        // check has not: only CI, which fetches them all, compares (see the module's header).
        println!(
            "THIRD-PARTY-NOTICES.txt not compared with Cargo.lock: set CROSSFX_CHECK_NOTICES=1 \
             after cargo fetch --locked to compare it"
        );
        return;
    }
    let generated = generate();
    let committed = fs::read_to_string(&path)
        .unwrap_or_default()
        .replace("\r\n", "\n");
    assert!(
        committed == generated,
        "THIRD-PARTY-NOTICES.txt is not what Cargo.lock produces; regenerate it with \
         CROSSFX_WRITE_NOTICES=1 cargo test -p crossfx-app --test third_party_notices"
    );
}

/// The file names the crates and the texts and nothing of the machine that generated it: no path
/// of the checkout or of the cargo registry, no CR, and a text for every crate the packages carry
/// the binary of (the egui crates, which ship none, among them, and the faces of
/// `epaint_default_fonts`).
#[test]
fn the_notices_are_the_same_on_every_machine_and_name_the_crates_that_ship_no_licence_file() {
    let bytes = fs::read(repo().join("THIRD-PARTY-NOTICES.txt")).expect("the file is read");
    let text = String::from_utf8(bytes).expect("the file is UTF-8");
    assert!(!text.contains('\r'), "the file has CR line ends");
    for machine in [
        repo().to_string_lossy().replace('\\', "/"),
        repo().to_string_lossy().to_string(),
        ".cargo/registry".to_string(),
        "index.crates.io-".to_string(),
    ] {
        assert!(
            !text.contains(&machine),
            "the file names a place of the machine that generated it: {machine}"
        );
    }
    for needed in [
        "egui 0.37.0 (standard text)",
        "epaint_default_fonts 0.37.0 (fonts/OFL.txt)",
        "epaint_default_fonts 0.37.0 (fonts/UFL.txt)",
        "windows-sys ",
        "zbus ",
        "ksni ",
        "Copyright (c) Emil Ernerfeldt",
    ] {
        assert!(text.contains(needed), "the file does not have {needed}");
    }
    // The texts that sit below a crate's top folder and cover what it compiles in: the Unicode
    // tables of regex-syntax, a file of rfd's, and the protocol files the Wayland bindings are
    // generated from.
    for needed in [
        "(src/unicode_tables/LICENSE-UNICODE)",
        "(src/backend/xdg_desktop_portal/window_identifier/LICENSE)",
        "(protocols/COPYING)",
        "(plasma-wayland-protocols/COPYING.LIB)",
        "(plasma-wayland-protocols/LICENSES/MIT-CMU.txt)",
    ] {
        assert!(text.contains(needed), "the file does not have {needed}");
    }
    // Not a test's fixture, nor code the builds leave out, nor a crate cargo tree does not list
    // under crossfx-app for a shipped build (cargo metadata's resolve, which unifies the
    // features of the whole workspace and its tests, had these).
    let paths: Vec<&str> = text
        .lines()
        .filter_map(|line| {
            line.strip_prefix("  ")?
                .split_once(" (")?
                .1
                .strip_suffix(')')
        })
        .collect();
    for path in paths {
        assert!(
            !path.starts_with("tests/")
                && !path.contains("/tests/")
                && !path.starts_with("src/spin/"),
            "the file has {path}"
        );
    }
    for absent in [
        "  wgpu ",
        "  naga ",
        "  arboard ",
        "  tempfile ",
        "  zlib-rs ",
    ] {
        assert!(!text.contains(absent), "the file has {absent}");
    }
    assert!(
        !text.contains("crossfx-core 1.") && !text.contains("crossfx-app 1."),
        "the file lists a crate of the workspace"
    );
}

/// The comparison of THIRD-PARTY-NOTICES.txt with Cargo.lock needs the crates of every target on
/// disk, which a package build's check, offline and with its own target's crates, has not: no
/// recipe's test run turns it on, and every CI step that runs the workspace's tests in the debug
/// profile does, each job fetching every target's crates first.
#[test]
fn only_ci_compares_the_notices_with_cargo_lock() {
    for recipe in [
        "packaging/PKGBUILD",
        "packaging/fedora/crossfx.spec",
        "packaging/debian/rules",
    ] {
        assert!(
            !fs::read_to_string(repo().join(recipe))
                .expect("read")
                .contains("CROSSFX_CHECK_NOTICES"),
            "{recipe} turns on the comparison of the notices with Cargo.lock"
        );
    }
    let ci = fs::read_to_string(repo().join(".github/workflows/ci.yml")).expect("read");
    let runs = ci
        .lines()
        .filter(|line| line.contains("cargo test --workspace") && !line.contains("--release"))
        .count();
    assert!(runs > 0, "ci.yml runs no workspace tests");
    assert_eq!(
        ci.matches("CROSSFX_CHECK_NOTICES: \"1\"").count(),
        runs,
        "a CI step that runs the workspace's tests does not compare the notices"
    );
    assert_eq!(
        ci.lines()
            .filter(|line| line.trim_start().starts_with("run:")
                && line.trim_end().ends_with("cargo fetch --locked"))
            .count(),
        runs,
        "a CI job that compares the notices does not fetch every target's crates"
    );
}

/// Both Arch recipes say what license=() lists and where the Rust crates' licences are.
#[test]
fn the_arch_license_arrays_say_where_the_crates_licences_are() {
    for recipe in ["packaging/PKGBUILD", "packaging/aur/crossfx-bin/PKGBUILD"] {
        let pkgbuild = fs::read_to_string(repo().join(recipe)).expect("read");
        let lines: Vec<&str> = pkgbuild.lines().collect();
        let at = lines
            .iter()
            .position(|line| line.starts_with("license=("))
            .unwrap_or_else(|| panic!("{recipe} has no license=()"));
        let start = lines[..at]
            .iter()
            .rposition(|line| !line.starts_with('#'))
            .map_or(0, |before| before + 1);
        let comment = lines[start..at]
            .iter()
            .map(|line| line.trim_start_matches('#').trim())
            .collect::<Vec<_>>()
            .join(" ");
        assert!(
            comment.contains("THIRD-PARTY-NOTICES.txt") && comment.contains("not listed here"),
            "{recipe}: the comment over license=() does not say where the crates' licences are: \
             {comment}"
        );
    }
}
